begin;
select no_plan();
update app_settings set assistant_schedule_enabled=false;
insert into auth.users(id,email,email_confirmed_at,aud,role)
select ('97000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'schedule97-'||n||'@verify.local',now(),'authenticated','authenticated' from generate_series(1,3) n;
insert into profiles(id,gender,hub_id,company_email,name,onboarding_step)
select id,case when email like '%2@%' then 'female'::gender else 'male'::gender end,'gangnam',email,'가상일정',7 from auth.users where email like 'schedule97-%@verify.local';
insert into intros(id,male_id,female_id,closed_at,outcome) values('97000000-0000-0000-0000-000000000010','97000000-0000-0000-0000-000000000001','97000000-0000-0000-0000-000000000002',now(),'ticket_used');
insert into tickets(id,user_id,payment_id,price_krw,state,kind,intro_id,used_at,expires_at)
values('97000000-0000-0000-0000-000000000011','97000000-0000-0000-0000-000000000001','schedule97',30000,'used','meeting','97000000-0000-0000-0000-000000000010',now(),now()+interval '12 months');
insert into meetings(id,intro_id,ticket_id) values('97000000-0000-0000-0000-000000000012','97000000-0000-0000-0000-000000000010','97000000-0000-0000-0000-000000000011');
create temp table dates as select (((date_trunc('week',now() at time zone 'Asia/Seoul')+interval '7 days')::date)+time '19:00') at time zone 'Asia/Seoul' as d;
grant select on dates to authenticated;
select ok(not has_table_privilege('authenticated','assistant_actions','update'),'immutable action table');
select ok(not has_function_privilege('authenticated','assistant_check_schedule(uuid,text,jsonb)','execute'),'internal checker inaccessible');
select set_config('request.jwt.claim.sub','97000000-0000-0000-0000-000000000002',true);
select throws_ok($$select assistant_draft_schedule(gen_random_uuid(),'97000000-0000-0000-0000-000000000012','preferences',jsonb_build_object('dates',jsonb_build_array((select d from dates)),'stations','[]'::jsonb,'anywhere',true))$$,'PT403','feature disabled','schedule flag enforced');
update app_settings set assistant_schedule_enabled=true,assistant_chat_enabled=true;
select assistant_consent(true);
create temp table initial_notifications as select count(*)::int as n from notifications where meeting_id='97000000-0000-0000-0000-000000000012';
select lives_ok($$select assistant_draft_schedule('97000000-0000-0000-0000-000000000020','97000000-0000-0000-0000-000000000012','preferences',jsonb_build_object('dates',jsonb_build_array((select d from dates)),'stations','[]'::jsonb,'anywhere',true))$$,'female makes preferences draft');
select ok((select prefs_submitted_at is null from meetings where id='97000000-0000-0000-0000-000000000012'),'draft has no effect on meeting');
select is((select count(*)::int from notifications where meeting_id='97000000-0000-0000-0000-000000000012'),(select n from initial_notifications),'draft sends no notification');
select throws_ok($$select assistant_approve_schedule('97000000-0000-0000-0000-000000000020',(select approval_token from assistant_actions limit 1),false)$$,'42501','approval required','policy acknowledgement required');
select set_config('request.jwt.claim.sub','97000000-0000-0000-0000-000000000003',true);
select is(jsonb_array_length(my_assistant_schedule()->'actions'),0,'outsider sees no draft');
select throws_ok($$select assistant_approve_schedule('97000000-0000-0000-0000-000000000020',(select approval_token from assistant_actions limit 1),true)$$,'42501','approval required','outsider cannot approve');
select set_config('request.jwt.claim.sub','97000000-0000-0000-0000-000000000002',true);
select lives_ok($$select assistant_approve_schedule('97000000-0000-0000-0000-000000000020',(select approval_token from assistant_actions where id='97000000-0000-0000-0000-000000000020'),true)$$,'approved preferences call existing command');
select ok((select prefs_submitted_at is not null and female_attendance_policy_ack_at is not null from meetings where id='97000000-0000-0000-0000-000000000012'),'preferences and policy ack retained');
select lives_ok($$select assistant_approve_schedule('97000000-0000-0000-0000-000000000020',(select approval_token from assistant_actions where id='97000000-0000-0000-0000-000000000020'),true)$$,'repeated approval receipt');
select is((select count(*)::int from assistant_turns where source_id='97000000-0000-0000-0000-000000000020' and kind='schedule_applied'),1,'approved schedule writes exactly one conversation receipt');
select ok((select answer like '%가능한 시간을 전달%' from assistant_turns where source_id='97000000-0000-0000-0000-000000000020'),'schedule receipt describes preferences, not a confirmed meeting');
select throws_ok($$select assistant_draft_schedule(gen_random_uuid(),'97000000-0000-0000-0000-000000000012','confirm',jsonb_build_object('at',(select d from dates),'place','가상카페','placeKind','카페'))$$,'22023','invalid confirmation','female cannot bypass male confirmation role');
select set_config('request.jwt.claim.sub','97000000-0000-0000-0000-000000000001',true);
select assistant_draft_schedule('97000000-0000-0000-0000-000000000021','97000000-0000-0000-0000-000000000012','confirm',jsonb_build_object('at',(select d from dates),'place','가상카페','placeKind','카페'));
update meetings set prefs=prefs||'{"note":"changed"}'::jsonb where id='97000000-0000-0000-0000-000000000012';
select throws_ok($$select assistant_approve_schedule('97000000-0000-0000-0000-000000000021',(select approval_token from assistant_actions where id='97000000-0000-0000-0000-000000000021'),true)$$,'PT409','draft changed or expired','even non-revision changes invalidate draft');
select assistant_draft_schedule('97000000-0000-0000-0000-000000000022','97000000-0000-0000-0000-000000000012','confirm',jsonb_build_object('at',(select d from dates),'place','가상카페','placeKind','카페'));
select lives_ok($$select assistant_approve_schedule('97000000-0000-0000-0000-000000000022',(select approval_token from assistant_actions where id='97000000-0000-0000-0000-000000000022'),true)$$,'male confirms exact proposed date');
select is((select attendance_policy_version from meetings where id='97000000-0000-0000-0000-000000000012'),'checkin-v1','existing attendance lifecycle enrolled');
select assistant_draft_schedule('97000000-0000-0000-0000-000000000023','97000000-0000-0000-0000-000000000012','change',jsonb_build_object('at',(select d+interval '1 day' from dates)));
select lives_ok($$select assistant_approve_schedule('97000000-0000-0000-0000-000000000023',(select approval_token from assistant_actions where id='97000000-0000-0000-0000-000000000023'),true)$$,'change only requests partner approval');
select is((select scheduled_at from meetings where id='97000000-0000-0000-0000-000000000012'),(select d from dates),'own approval does not change partner schedule');
select assistant_approve_schedule('97000000-0000-0000-0000-000000000023',(select approval_token from assistant_actions where id='97000000-0000-0000-0000-000000000023'),true);
select is((select count(*)::int from meeting_change_requests where meeting_id='97000000-0000-0000-0000-000000000012'),1,'reconnected retry cannot duplicate change');
select is((select count(*)::int from notifications where meeting_id='97000000-0000-0000-0000-000000000012' and kind='meeting_change_requested'),1,'one partner notification');
select is((select count(*)::int from tickets where user_id='97000000-0000-0000-0000-000000000001'),1,'no extra ticket charge');
update meeting_change_requests set state='withdrawn' where meeting_id='97000000-0000-0000-0000-000000000012';
select assistant_draft_schedule('97000000-0000-0000-0000-000000000024','97000000-0000-0000-0000-000000000012','change',jsonb_build_object('at',(select d+interval '2 days' from dates)));
update app_settings set assistant_schedule_enabled=false;
select throws_ok($$select assistant_approve_schedule('97000000-0000-0000-0000-000000000024',(select approval_token from assistant_actions where id='97000000-0000-0000-0000-000000000024'),true)$$,'PT403','feature disabled','kill switch checked again at execution');
select lives_ok($$select assistant_revoke_schedule('97000000-0000-0000-0000-000000000024')$$,'revocation works while off');
update app_settings set assistant_schedule_enabled=true;
select throws_ok($$select assistant_approve_schedule('97000000-0000-0000-0000-000000000024',(select approval_token from assistant_actions where id='97000000-0000-0000-0000-000000000024'),true)$$,'PT409','draft changed or expired','revoked draft cannot execute');
select assistant_draft_schedule('97000000-0000-0000-0000-000000000025','97000000-0000-0000-0000-000000000012','change',jsonb_build_object('at',(select d+interval '2 days' from dates)));
update assistant_actions set expires_at=now()-interval '1 second' where id='97000000-0000-0000-0000-000000000025';
select throws_ok($$select assistant_approve_schedule('97000000-0000-0000-0000-000000000025',(select approval_token from assistant_actions where id='97000000-0000-0000-0000-000000000025'),true)$$,'PT409','draft changed or expired','expired draft cannot execute');
update meetings set confirmed_at=null,scheduled_at=null,proposed_slots=array[(select d from dates)],proposed_place_name='가상카페'
where id='97000000-0000-0000-0000-000000000012';
select throws_ok($$select assistant_draft_schedule(gen_random_uuid(),'97000000-0000-0000-0000-000000000012','accept_slot','{"slot":0}'::jsonb)$$,'PT409','slot unavailable','male cannot accept own slot');
select set_config('request.jwt.claim.sub','97000000-0000-0000-0000-000000000002',true);
select throws_ok($$select assistant_draft_schedule(gen_random_uuid(),'97000000-0000-0000-0000-000000000012','accept_slot','{"slot":0,"hidden":"payload"}'::jsonb)$$,'22023','hidden draft fields','no hidden approval payload');
select assistant_draft_schedule('97000000-0000-0000-0000-000000000026','97000000-0000-0000-0000-000000000012','accept_slot','{"slot":0}'::jsonb);
select is((select (preview->'dates'->>0)::timestamptz from assistant_actions where id='97000000-0000-0000-0000-000000000026'),(select d from dates),'preview is immutable exact slot date');
select lives_ok($$select assistant_approve_schedule('97000000-0000-0000-0000-000000000026',(select approval_token from assistant_actions where id='97000000-0000-0000-0000-000000000026'),true)$$,'female slot approval uses existing command');
select is((select accepted_slot::int from meetings where id='97000000-0000-0000-0000-000000000012'),0,'accepted slot persisted');
select assistant_draft_schedule('97000000-0000-0000-0000-000000000027','97000000-0000-0000-0000-000000000012','change',jsonb_build_object('at',(select d+interval '2 days' from dates)));
update meetings set cancelled_at=now() where id='97000000-0000-0000-0000-000000000012';
select throws_ok($$select assistant_approve_schedule('97000000-0000-0000-0000-000000000027',(select approval_token from assistant_actions where id='97000000-0000-0000-0000-000000000027'),true)$$,'PT409','draft changed or expired','cancelled meeting cannot execute a pending draft');
select * from finish();
rollback;
